import{_ as o,o as e,c as r,ag as d}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"定时任务故障与整理（2026-09-23 ~ 10-08）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-brain/cron-outage-2026-09-23.md","filePath":"topics/ai-brain/cron-outage-2026-09-23.md"}'),n={name:"topics/ai-brain/cron-outage-2026-09-23.md"};function a(c,t,s,i,l,h){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="定时任务故障与整理-2026-09-23-10-08" tabindex="-1">定时任务故障与整理（2026-09-23 ~ 10-08） <a class="header-anchor" href="#定时任务故障与整理-2026-09-23-10-08" aria-label="Permalink to &quot;定时任务故障与整理（2026-09-23 ~ 10-08）&quot;">​</a></h1><blockquote><p><strong>一句话</strong>：2026-09-23 起，本机 5 个定时任务中 <strong>4 个 agent 型任务连续 16 天运行失败</strong>（<code>RuntimeError: Connection error.</code>），同期飞书投递被本地代理阻断，用户全程零感知；<strong>10-08 手动触发验证已恢复</strong>，并完成缺口盘点与一项源码修复。</p></blockquote><blockquote><p>关键词：定时任务故障、cron FAILED、Connection error、代理单点故障、raw.githubusercontent 不可达、多源回退、期号重复、静默期、外脑运维</p></blockquote><hr><h2 id="_1-时间线" tabindex="-1">1. 时间线 <a class="header-anchor" href="#_1-时间线" aria-label="Permalink to &quot;1. 时间线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>事件</th></tr></thead><tbody><tr><td>2026-09-22</td><td><strong>最后一次全线正常</strong>（5 个任务当日输出均为 OK，无 FAILED 标记）</td></tr><tr><td>2026-09-21</td><td>「每周维护」已开始 FAILED（比其余任务早 2 天）</td></tr><tr><td>2026-09-23</td><td><strong>agent 型任务全线 FAILED</strong>，此后每天只留 prompt 注入、零产出</td></tr><tr><td>09-23 ~ 10-07</td><td>用户在知识库<strong>无任何新对话</strong>（<code>state.db</code> 无真实用户会话，只有 cron prompt）→ 静默期 16 天</td></tr><tr><td>2026-10-08 09:05</td><td>用户发「11-1」探测在线状态，发现异常</td></tr><tr><td>2026-10-08 09:17</td><td><strong>手动触发「外脑今日洞察」→ <code>last_status: ok</code></strong>，通路确认恢复，产出落盘并提交（<code>3500f64</code>）</td></tr></tbody></table><h2 id="_2-影响面-缺口清单" tabindex="-1">2. 影响面（缺口清单） <a class="header-anchor" href="#_2-影响面-缺口清单" aria-label="Permalink to &quot;2. 影响面（缺口清单）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>任务</th><th>最后成功</th><th>缺口</th><th>说明</th></tr></thead><tbody><tr><td>外脑今日洞察</td><td>09-22</td><td>09-23 ~ 10-07（15 天）</td><td>已于 10-08 补跑成功</td></tr><tr><td>科学日报（本机）</td><td>09-22</td><td>09-17~09-20、09-23~09-28、10-01、10-02、10-08（13 天）</td><td>云端兜底仅覆盖其中 7 天（09-29、09-30、10-03~10-07）</td></tr><tr><td>外脑做梦</td><td>09-22</td><td>09-23 ~ 10-08</td><td><strong>非故障所致</strong>：这些天没有用户对话，<code>dream_scan.py</code> 实测返回 <code>NO_DATA</code>（无素材）</td></tr><tr><td>阮一峰周刊监控</td><td>09-22</td><td>0 期</td><td>实测最新 413 期 = 已处理 413 期，<strong>无漏报</strong>；脚本另有源故障，已修</td></tr><tr><td>每周维护</td><td>09-14</td><td>09-21、09-28、10-05</td><td>未补跑</td></tr></tbody></table><p>**「已生成的不用处理」**所指：云端 GitHub Actions 兜底生成的 09-29、09-30、10-03~10-07 共 7 篇日报（存于 ScienceDaily 仓库）。</p><h2 id="_3-根因-三条独立故障-不是一条" tabindex="-1">3. 根因（三条独立故障，不是一条） <a class="header-anchor" href="#_3-根因-三条独立故障-不是一条" aria-label="Permalink to &quot;3. 根因（三条独立故障，不是一条）&quot;">​</a></h2><h3 id="_3-1-agent-型-cron-runtimeerror-connection-error" tabindex="-1">3.1 agent 型 cron：<code>RuntimeError: Connection error.</code> <a class="header-anchor" href="#_3-1-agent-型-cron-runtimeerror-connection-error" aria-label="Permalink to &quot;3.1 agent 型 cron：`RuntimeError: Connection error.`&quot;">​</a></h3><p>LLM 调用失败，任务在第一步就中断，因此<strong>只留下 prompt、没有任何产出</strong>。 10-08 09:12 实测：内网端点（<code>10.111.32.151:3001</code>）与公网端点（<code>ai.bjxm.tech:8443</code>）<strong>绕代理与走代理均成功</strong>，代理 <code>127.0.0.1:8899</code> 进程存活 → 属<strong>当时</strong>的网络/代理故障，现已恢复。</p><h3 id="_3-2-飞书投递-proxyerror-tunnel-connection-failed-503" tabindex="-1">3.2 飞书投递：<code>ProxyError: Tunnel connection failed: 503</code> <a class="header-anchor" href="#_3-2-飞书投递-proxyerror-tunnel-connection-failed-503" aria-label="Permalink to &quot;3.2 飞书投递：`ProxyError: Tunnel connection failed: 503`&quot;">​</a></h3><p>出站消息同样经过本地代理，代理 503 → 即使任务跑成，消息也送不出去（<code>last_delivery_error</code> 记录在案）。10-08 实测 <code>open.feishu.cn</code> 返回 200，已恢复。</p><h3 id="_3-3-周刊监控-raw-githubusercontent-com-完全不可达-独立根因-与故障窗口无关" tabindex="-1">3.3 周刊监控：<code>raw.githubusercontent.com</code> 完全不可达（<strong>独立根因，与故障窗口无关</strong>） <a class="header-anchor" href="#_3-3-周刊监控-raw-githubusercontent-com-完全不可达-独立根因-与故障窗口无关" aria-label="Permalink to &quot;3.3 周刊监控：`raw.githubusercontent.com` 完全不可达（**独立根因，与故障窗口无关**）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>路径</th><th>结果</th></tr></thead><tbody><tr><td>直连</td><td><code>000</code>（失败）</td></tr><tr><td>走代理</td><td><code>000</code>（失败）</td></tr><tr><td>Python urllib</td><td><code>EOF occurred in violation of protocol (_ssl.c:1007)</code></td></tr><tr><td><code>api.github.com</code></td><td>✅ 正常（Contents API + <code>Accept: application/vnd.github.raw</code> 可取原文）</td></tr></tbody></table><p>结论：<strong>这不是代理挂掉导致的，是该域名在本机网络下被阻断</strong>——即使其它一切正常，周刊监控也会一直失败。</p><h2 id="_4-已修复" tabindex="-1">4. 已修复 <a class="header-anchor" href="#_4-已修复" aria-label="Permalink to &quot;4. 已修复&quot;">​</a></h2><ul><li><strong><code>scripts/weekly_watch.py</code></strong> → 改为<strong>多源按序回退</strong>（<code>api.github.com</code> → <code>raw</code> → <code>jsdelivr</code>），并把数据源信息在 <code>NEW</code> 分支输出、失败时聚合各源错误；实测 <code>NO</code>（最新 413 = 已处理，无漏期）。</li><li><strong><code>scripts/tests/test_watch.py</code></strong> → mock 签名适配新实现，并<strong>新增 2 条覆盖</strong>（多源回退：首源失败自动换源；多源全失败 → 返回 <code>None</code> + 错误详情）。</li><li><strong>契约修复（由自测抓出）</strong>：<code>NO</code> 必须<strong>单独一行</strong>输出——cron 靠它判定静默。首版修复中我在 <code>NO</code> 后多打了一行说明，<code>test_watch</code> 立刻报错；已改回严格单行。</li><li><code>scripts/tests/run_all.py</code>：<strong>全部通过 ✅</strong>。</li></ul><h2 id="_5-待办-未修" tabindex="-1">5. 待办（未修） <a class="header-anchor" href="#_5-待办-未修" aria-label="Permalink to &quot;5. 待办（未修）&quot;">​</a></h2><ol><li><strong>ScienceDaily 期号重复 bug</strong>：云端兜底生成的 09-29 ~ 10-07 <strong>7 篇日报全部标「第30期」</strong>（<code>generate_daily.py</code> 每次从 README 读期号再 +1，而 README 的「最新一期」表停在 09-22 的第29期）→ 同一期号重复 7 次，README 也停更。 修法建议：期号取 <code>max(README 期号, daily/ 目录已有最大期号) + 1</code>；同时补 README 的 09-23 ~ 10-08 行。</li><li><strong>13 天日报缺口</strong>（09-17~09-20、09-23~09-28、10-01、10-02、10-08）：补录需按 <strong>arXiv <code>submittedDate</code> 区间</strong>回查当日提交，属新增能力（现有脚本只抓&quot;此刻最新&quot;，不能直接回填历史）。</li><li><strong>09-22 晨报留的两条旧账</strong>（检查后仍未完成）：<code>knowledge-system-arsenal.md</code> 的 Echo Gap 旁加「投递文本 ≠ 执行记录」判据；新建 <code>topics/ai-brain/source-verification-checklist.md</code>。</li><li><strong>每周维护</strong> 09-21、09-28、10-05 未跑。</li></ol><h2 id="_6-教训-写给下次的自己" tabindex="-1">6. 教训（写给下次的自己） <a class="header-anchor" href="#_6-教训-写给下次的自己" aria-label="Permalink to &quot;6. 教训（写给下次的自己）&quot;">​</a></h2><ul><li><strong>「任务在跑」≠「任务跑成了」</strong>：cron 每天都按时触发、<code>state.db</code> 里每天都留下 prompt，但产出为 0。判断任务健康必须看<strong>产物文件</strong>与 <code>last_status</code>，不能看触发记录。</li><li><strong>本地代理是单点故障</strong>：<code>http_proxy=http://127.0.0.1:8899</code> 一挂，<strong>LLM 调用与飞书投递同时失效</strong>，表现出来却像&quot;定时任务自己没运行&quot;，极易误判为任务配置问题。</li><li><strong>依赖单一境外源 = 静默失效</strong>：<code>raw.githubusercontent.com</code> 被阻断后，脚本只报一行 <code>ERR</code> 就静默了，没人发现。<strong>多源回退 + 自测护栏</strong>是必要条件。</li><li><strong>自测抓到了两次真问题</strong>（mock 失配、<code>NO</code> 契约破坏）——改脚本后跑 <code>python3 scripts/tests/run_all.py</code> 不是形式，是护栏。</li></ul>',23)])])}const b=o(n,[["render",a]]);export{u as __pageData,b as default};
